#pragma once

#include "agino-gpu/root.h"
#include "agino-gpu/types.h"

#include <QByteArray>
#include <QList>
#include <QString>

namespace AginoGpu {

// Generated files (design.md §4, §6.3). Every one starts with
// "# Generated by agino-gpu; do not edit." and the library only ever creates or deletes these
// exact paths.
inline constexpr char kXorgDedicatedPath[] = "/etc/X11/xorg.conf.d/90-agino-gpu.conf";
inline constexpr char kModprobeIntegratedPath[] = "/etc/modprobe.d/agino-gpu-integrated.conf";
inline constexpr char kOffloadEnvPath[] = "/run/agino-gpu/offload.env";
inline constexpr char kModePath[] = "/etc/agino-gpu/mode";
inline constexpr char kStatePath[] = "/run/agino-gpu/state";
inline constexpr char kLastFailurePath[] = "/var/lib/agino-gpu/last-failure";

QByteArray generatedHeader(); // "# Generated by agino-gpu; do not edit.\n"

// §4.3: OutputClass section for the discrete GPU's driver (nvidia-drm -> Driver "nvidia" with
// the two ModulePaths; amdgpu / i915 / xe matched by MatchDriver plus the PCI BusID of the
// discrete GPU so the integrated GPU of the same driver is not matched).
QByteArray xorgDedicatedConfig(const Gpu &dgpu);

// §4.2: "blacklist <module>" and "install <module> /bin/false" for nvidia, nvidia_drm,
// nvidia_modeset, nvidia_uvm when the discrete GPU is NVIDIA; empty QByteArray for AMD/Intel
// (they are only PCI-removed).
QByteArray modprobeIntegratedConfig(const Gpu &dgpu);

// The set of generated files a mode needs, path -> contents. Paths not in the map but listed
// in allGeneratedPaths() must be removed. offload.env is NOT included (it belongs to the boot
// state, written by agino-gpu-apply / the daemon from offloadEnvironment()).
struct GeneratedFile
{
    QString path;
    QByteArray contents;
};
QList<GeneratedFile> generatedFilesForMode(const Hardware &hw, Mode mode);
QStringList allGeneratedPaths(); // xorg + modprobe

// Applies generatedFilesForMode(): writes the needed files, removes the others. Never touches
// files without the generated header (returns false with an error instead).
bool applyGeneratedFiles(const Root &root, const Hardware &hw, Mode mode, QString *error = nullptr);

} // namespace AginoGpu
